// Run: bun src/features/cart/cart.check.ts
import { addItem, applyDiscount, cartSummary, discountCents, emptyCart, removeDiscount, removeItem, totalCents } from './index';

function check(ok: boolean, message: string): void {
  if (!ok) throw new Error(`FAIL: ${message}`);
}

const mug = { productId: 'mug', name: 'Mug', unitPriceCents: 1999, quantity: 1 };
const cart = { ...addItem(emptyCart(), mug), discount: { code: 'SAVE15', percent: 15 } };

check(discountCents(cart) === 300, '15% of $19.99 rounds to 300 cents');
check(totalCents(cart) === 1699, 'the discount comes off the total');
check(cartSummary(cart).includes('Discount SAVE15 (15%): -$3.00'), 'the summary shows the discount');
check(addItem(cart, mug).discount?.code === 'SAVE15', 'adding an item keeps the code');
check(totalCents(removeItem(cart, 'mug')) === 0, 'an empty cart totals 0 with a code');
check(totalCents(removeDiscount(cart)) === 1999, 'removing the code restores the total');

let response: unknown;
let sentBody: unknown;
Object.assign(globalThis, {
  localStorage: { getItem: () => null },
  fetch: async (_url: string, init: RequestInit) => {
    sentBody = init.body;
    return new Response(JSON.stringify(response));
  },
});

async function rejects(code: string): Promise<boolean> {
  return applyDiscount(cart, code).then(
    () => false,
    () => true,
  );
}

async function main(): Promise<void> {
  response = { percent: 10 };
  const applied = await applyDiscount(emptyCart(), 'TEN');
  check(applied.discount?.percent === 10 && sentBody === '{"code":"TEN"}', 'applies the percent the server returns');
  for (const bad of [{ percent: 150 }, { percent: 0 }, { percent: '10' }, {}, null]) {
    response = bad;
    check(await rejects('BAD'), `rejects ${JSON.stringify(bad)}`);
  }
  console.log('cart checks pass');
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
EOF
